import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  LeaveGroup Request (Version: 0) => group_id member_id
    group_id => STRING
    member_id => STRING
*/
export function createRequest(groupId, members) {
    return Writer.create().appendString(groupId, false).appendString(members[0]?.memberId, false);
}
/*
  LeaveGroup Response (Version: 0) => error_code
    error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = { throttleTimeMs: 0, errorCode: reader.readInt16(), members: [] };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(13, 0, createRequest, parseResponse, false, false);
